package cn.zhuatech.psa.service;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;class ProjectFinancialClosureServiceTest{private final ProjectFinancialClosureService service=new ProjectFinancialClosureService();@Test void closesFinanciallyCompleteProject(){var r=service.assess(new ProjectFinancialClosureService.Request("P1",true,true,true,true,true,0,0,true));assertThat(r.decision()).isEqualTo(ProjectFinancialClosureService.Decision.CLOSE);}@Test void blocksUnfinishedFinancialControls(){var r=service.assess(new ProjectFinancialClosureService.Request("P2",false,false,false,false,false,2,0,true));assertThat(r.blockers()).hasSize(6);}@Test void reviewsWipAndLessons(){var r=service.assess(new ProjectFinancialClosureService.Request("P3",true,true,true,true,true,0,1000,false));assertThat(r.actions()).hasSize(2);}}
